PageReference page = new PageReference('/apex/Local');
System.assertEquals(0, page.getCookies().size());
Cookie sid = new Cookie('sid', 'abc', '/', 60, true);
Cookie theme = new Cookie('theme', 'dark', null, 100, false);
page.setCookies(new List<Cookie>{sid, theme});
System.assertEquals(2, page.getCookies().size());
System.assertEquals('abc', page.getCookies().get('sid').getValue());
System.assertEquals('dark', page.getCookies().get('theme').getValue());

